import { PurchaseStatus } from '@flash-sale-demo/shared-types';
import { pgEnum, pgTable, text, timestamp, uuid } from 'drizzle-orm/pg-core';
import { flashSales } from './flash-sales';

export const purchaseStatusEnum = pgEnum(
  'purchase_status',
  Object.values(PurchaseStatus) as [PurchaseStatus, ...PurchaseStatus[]],
);

/**
 * Audit trail of every purchase attempt that reached the worker.
 * The id is generated by the API and travels with the SQS message,
 * which makes redelivered messages easy to detect.
 */
export const purchaseRequests = pgTable('purchase_requests', {
  id: uuid().primaryKey(),
  flashSaleId: uuid()
    .notNull()
    .references(() => flashSales.id),
  userId: text().notNull(),
  status: purchaseStatusEnum().notNull(),
  /** When the API accepted the request; used to judge the sale window. */
  acceptedAt: timestamp({ withTimezone: true }).notNull(),
  processedAt: timestamp({ withTimezone: true }),
});

export type PurchaseRequest = typeof purchaseRequests.$inferSelect;
export type NewPurchaseRequest = typeof purchaseRequests.$inferInsert;
